function paperPrice(){return Number(state.live?.ticker?.last||state.analysis?.price);}
function expiryLabel(ms){if(ms>=60000)return `${Math.round(ms/60000)} min`;return `${Math.round(ms/1000)} s`;}
function countdown(ms){const total=Math.max(0,Math.ceil(Number(ms)/1000)),m=Math.floor(total/60),s=total%60;return `${String(m).padStart(2,"0")}:${String(s).padStart(2,"0")}`;}
function updateOrderPreview(){if(!$("orderPreview"))return;const stake=Number($("paperQty").value),price=paperPrice(),duration=Number($("paperExpiry").value);if(!(stake>0)||!(price>0)){$("orderPreview").textContent="Escolha se o preço estará acima ou abaixo ao terminar o tempo.";return;}const direction=state.side==="buy"?"acima":"abaixo",profit=stake*Number(state.paper?.payoutRate||.82);$("orderPreview").textContent=`${money(stake)} em ${state.symbol.replace("USDT","/USDT")}: você vence se o preço terminar ${direction} de ${priceFormat(price)} após ${expiryLabel(duration)}. Lucro no acerto: ${money(profit)}.`;}
async function submitPaper(e){e.preventDefault();const button=e.submitter||e.currentTarget.querySelector('[type="submit"]'),stake=Number($("paperQty").value),price=paperPrice(),durationMs=Number($("paperExpiry").value),idempotencyKey=crypto.randomUUID(),signal=state.analysis?.signalLifecycle;$("paperMessage").textContent="";button.disabled=true;try{if(!(stake>=1)||!(price>0))throw new Error("Informe um valor a partir de US$ 1 e aguarde o preço ao vivo.");if(stake>(state.paper?.balance||0))throw new Error(`Saldo virtual insuficiente. Disponível: ${money(state.paper?.balance||0)}.`);const out=await api("/api/paper/order",{method:"POST",body:JSON.stringify({symbol:state.symbol,direction:state.side==="buy"?"up":"down",stake,durationMs,interval:state.interval,note:$("paperNote").value,idempotencyKey,signalId:signal?.signalId||null,analysisId:state.analysis?.id||null})});state.paper=out.portfolio;renderPaper();const confirmedAt=Number(out.confirmedEntryPriceAt)>0?new Date(Number(out.confirmedEntryPriceAt)).toLocaleTimeString("pt-BR"):"agora";$("paperMessage").textContent=`Entrada confirmada em ${priceFormat(out.confirmedEntryPrice)} às ${confirmedAt}; resultado em ${expiryLabel(durationMs)}${out.trade.signalId?` · sinal ${out.trade.signalId.slice(0,8)}`:""}.`;toast(`Entrada demo confirmada em ${priceFormat(out.confirmedEntryPrice)}`);}catch(error){$("paperMessage").textContent=error.message;toast(error.message,true);}finally{button.disabled=false;}}
function notifyPaperResult(result){toast(result.result==="win"?`Acerto: +${money(result.profit)}`:result.result==="draw"?"Empate: valor devolvido":result.result==="unresolved"?"Cotação de encerramento indisponível; valor devolvido.":`Perda: ${money(Math.abs(result.profit))}`,result.result==="loss");}
function paperSignature(p){return JSON.stringify([p?.updatedAt,p?.balance,p?.realized,p?.open?.map(x=>[x.id,x.status,x.currentPrice]),p?.results?.[0]?.id]);}
async function refreshPaper(){try{const latest=await api("/api/paper"),signature=paperSignature(latest),previous=state.lastResultId,unseen=[];for(const result of latest.results||[]){if(result.id===previous)break;unseen.push(result);}if(latest.results?.[0])state.lastResultId=latest.results[0].id;unseen.reverse().forEach(notifyPaperResult);state.paper=latest;if(signature!==state.paperSignature){state.paperSignature=signature;renderPaper();}else updatePaperCountdowns();}catch(error){console.warn("Falha ao atualizar simulador:",error.message);}}
function updatePaperCountdowns(){document.querySelectorAll("[data-expires-at]").forEach(el=>{const remaining=Math.max(0,Number(el.dataset.expiresAt)-Date.now());el.textContent=remaining>0?countdown(remaining):"LIQUIDANDO";});}
async function resetPaper(){if(!confirm("Apagar todo o histórico do simulador e restaurar US$ 10.000?"))return;try{state.paper=await api("/api/paper/reset",{method:"POST",body:JSON.stringify({confirm:true})});state.lastResultId="__empty__";renderPaper();$("paperMessage").textContent="Saldo restaurado para US$ 10.000.";toast("Simulador restaurado");}catch(error){toast(error.message,true);}}
async function savePaperSettings(){try{state.paper=await api("/api/paper/settings",{method:"POST",body:JSON.stringify({payoutRate:Number($("paperPayout").value)})});renderPaper();toast("Retorno demo atualizado");}catch(error){toast(error.message,true);}}
async function exportPaper(){try{const response=await fetch("/api/paper/export",{headers:{"X-Dief-Token":state.token}});if(!response.ok)throw new Error("Não foi possível exportar o histórico.");const complete=response.headers.get("x-dief-history-complete")!=="0",unavailable=Number(response.headers.get("x-dief-history-unavailable")||0),blob=await response.blob(),link=document.createElement("a");link.href=URL.createObjectURL(blob);link.download="historico-dieftrade.csv";document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(link.href),1000);toast(complete?"Histórico completo exportado":`Exportação concluída, mas ${unavailable} registro(s) antigo(s) já não estavam disponíveis.`,!complete);}catch(error){toast(error.message,true);}}
function renderPaper(){const p=state.paper;if(!p)return;$("cash").textContent=money(p.balance);$("equity").textContent=money(p.locked);$("paperReturn").textContent=money(p.realized);$("paperReturn").className=p.realized>=0?"positive":"negative";$("realized").textContent=`${fmt(p.winRate,1)}% · ${p.wins||0}V/${p.losses||0}D${p.draws?` · ${p.draws}E`:""}${p.unresolved?` · ${p.unresolved} devolvida(s)`:""}`;$("payoutRate").textContent=`${Math.round(Number(p.payoutRate||.82)*100)}%`;$("paperPayout").value=String(Number(p.payoutRate||.82).toFixed(2));$("profitFactor").textContent=p.profitFactor==null?"∞":fmt(p.profitFactor,2);$("expectancy").textContent=money(p.expectancy);$("maxDrawdown").textContent=`${fmt(p.maxDrawdown,2)}%`;$("currentStreak").textContent=p.currentStreak>0?`${p.currentStreak} acertos`:p.currentStreak<0?`${Math.abs(p.currentStreak)} perdas`:"neutra";$("learningSamples").textContent=state.analysis?.calibration?.samples??state.calibration?.samples??0;$("positions").innerHTML=(p.open||[]).map(x=>`<div class="list-row trade-open"><span><b class="${x.direction==="up"?"positive":"negative"}">${x.direction==="up"?"▲ ALTA":"▼ BAIXA"}</b> ${esc(x.symbol)}<small> · ${money(x.stake)}</small><br><small>Entrada ${fmt(x.entryPrice,8)} · Agora ${fmt(x.currentPrice,8)}${x.note?` · ${esc(x.note)}`:""}</small></span><strong class="countdown" data-expires-at="${Number(x.expiresAt)}">${x.remainingMs>0?countdown(x.remainingMs):"LIQUIDANDO"}</strong></div>`).join("")||`<p class="legal">Nenhuma operação em andamento. Escolha Alta ou Baixa para começar.</p>`;$("trades").innerHTML=(p.results||[]).slice(0,50).map(t=>`<div class="list-row"><span><b class="${t.result==="win"?"positive":t.result==="loss"?"negative":""}">${t.result==="win"?"GANHOU":t.result==="loss"?"PERDEU":t.result==="unresolved"?"DEVOLVIDA":"EMPATE"}</b> ${esc(t.symbol)}<small> · ${t.direction==="up"?"ALTA":"BAIXA"}${t.analysisSnapshot?.signal?` · painel ${esc(t.analysisSnapshot.signal)}`:""}${t.note?` · ${esc(t.note)}`:""}${t.settlementReason?` · ${esc(t.settlementReason)}`:""}</small></span><small class="${t.profit>=0?"positive":"negative"}">${t.profit>=0?"+":""}${money(t.profit)}<br>${fmt(t.entryPrice,8)} → ${fmt(t.exitPrice,8)}</small></div>`).join("")||`<p class="legal">Seus resultados aparecerão aqui ao terminar o tempo.</p>`;updateOrderPreview();drawPaperEquity();}
function drawPaperEquity(){const canvas=$("equityChart"),rows=state.paper?.equityCurve||[];if(!canvas||!rows.length)return;const box=canvas.parentElement,dpr=devicePixelRatio||1,w=box.clientWidth,h=box.clientHeight;canvas.width=w*dpr;canvas.height=h*dpr;const ctx=canvas.getContext("2d");ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);const values=rows.map(x=>Number(x.value)),min=Math.min(...values),max=Math.max(...values),range=Math.max(1,max-min),x=i=>12+i/Math.max(1,rows.length-1)*(w-24),y=v=>12+(max-v)/range*(h-24);ctx.strokeStyle="#35e083";ctx.lineWidth=2;ctx.beginPath();rows.forEach((row,i)=>i?ctx.lineTo(x(i),y(row.value)):ctx.moveTo(x(i),y(row.value)));ctx.stroke();ctx.lineTo(w-12,h-10);ctx.lineTo(12,h-10);ctx.closePath();ctx.fillStyle="#35e08318";ctx.fill();ctx.fillStyle=getComputedStyle(document.body).getPropertyValue("--muted")||"#789083";ctx.font="10px Segoe UI";ctx.fillText(money(max),12,12);ctx.fillText(money(min),12,h-5);}
async function submitAlert(e){e.preventDefault();const button=e.submitter||e.currentTarget.querySelector('[type="submit"]');button.disabled=true;try{const item=await api("/api/alerts",{method:"POST",body:JSON.stringify({symbol:state.symbol,interval:state.interval,kind:$("alertKind").value,value:Number($("alertValue").value),note:$("alertNote").value})});state.alerts.unshift(item);renderAlerts();toast("Alerta criado");}catch(error){toast(error.message,true);}finally{button.disabled=false;}}
function updateAlertValue(){const kind=$("alertKind").value,needsValue=["price_gte","price_lte","confidence_gte"].includes(kind);$("alertValueLabel").style.display=needsValue?"block":"none";$("alertValue").required=needsValue;$("alertValue").placeholder=kind==="confidence_gte"?"Ex.: 70":"Preço-alvo";}
function alertDescription(a){if(a.kind==="price_gte")return `preço ≥ ${fmt(a.value,8)}`;if(a.kind==="price_lte")return `preço ≤ ${fmt(a.value,8)}`;if(a.kind==="signal_buy")return `novo sinal COMPRA confirmado em ${a.interval}`;if(a.kind==="signal_sell")return `novo sinal VENDA confirmado em ${a.interval}`;return `leitura ativa com qualidade ≥ ${fmt(a.value,0)}% em ${a.interval}`;}
function renderAlerts(){$("alertsList").innerHTML=state.alerts.map(a=>`<div class="list-row"><span><b class="${a.active?"":"positive"}">${esc(a.symbol)}</b><small> ${esc(alertDescription(a))}${a.active?"":" · DISPARADO"}${a.note?` · ${esc(a.note)}`:""}</small></span><button type="button" class="danger" aria-label="Excluir alerta" data-alert="${a.id}">×</button></div>`).join("")||`<p class="legal">Nenhum alerta configurado.</p>`;$("alertsList").querySelectorAll("[data-alert]").forEach(b=>b.onclick=async()=>{try{await api(`/api/alerts/${b.dataset.alert}`,{method:"DELETE"});state.alerts=state.alerts.filter(x=>x.id!==b.dataset.alert);renderAlerts();}catch(error){toast(error.message,true);}});}
function notifyAlert(alert){toast(`Alerta ${alert.symbol}: ${alertDescription(alert)}${alert.note?` · ${alert.note}`:""}`);if(preferences().alertSound===false)return;try{const audio=new AudioContext(),osc=audio.createOscillator(),gain=audio.createGain();osc.frequency.value=880;gain.gain.setValueAtTime(.09,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.32);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+.33);}catch(error){console.warn("Som de alerta indisponível:",error.message);}}
async function submitJournal(e){e.preventDefault();const button=e.submitter||e.currentTarget.querySelector('[type="submit"]');button.disabled=true;try{await api("/api/journal",{method:"POST",body:JSON.stringify({symbol:state.symbol,interval:state.interval,setup:$("journalSetup").value,note:$("journalNote").value,side:"observe"})});$("journalSetup").value="";$("journalNote").value="";await loadJournal({offset:0});toast("Anotação salva");}catch(error){toast(error.message,true);}finally{button.disabled=false;}}
async function loadJournal({offset=state.journalPage.offset,query=state.journalPage.query}={}){try{const page=await api(`/api/journal?offset=${Math.max(0,offset)}&limit=${state.journalPage.limit}&q=${encodeURIComponent(query||"")}`);state.journal=page.items||[];state.journalPage={...state.journalPage,...page};renderJournal();}catch(error){toast(error.message,true);}}
function renderJournal(){$("journalList").innerHTML=state.journal.map(j=>`<div class="list-row"><span><b>${esc(j.symbol)}</b> ${esc(j.setup||"Observação")}<small> ${new Date(j.createdAt).toLocaleString("pt-BR")}${j.note?` · ${esc(j.note)}`:""}</small></span><button type="button" class="danger" aria-label="Excluir anotação" data-journal="${j.id}">×</button></div>`).join("")||`<p class="legal">Nenhuma anotação encontrada.</p>`;const p=state.journalPage,start=p.total?Math.min(p.total,p.offset+1):0,end=Math.min(p.total,p.offset+state.journal.length);$("journalPageInfo").textContent=`${start}–${end} de ${p.total}`;$("journalPrev").disabled=p.offset<=0;$("journalNext").disabled=!p.hasMore;$("journalList").querySelectorAll("[data-journal]").forEach(b=>b.onclick=async()=>{try{await api(`/api/journal/${b.dataset.journal}`,{method:"DELETE"});await loadJournal({offset:state.journal.length===1?Math.max(0,p.offset-p.limit):p.offset});}catch(error){toast(error.message,true);}});}
async function saveAi(e){e.preventDefault();try{const key=$("aiKey").value.trim(),provider=$("aiProvider").value;if(!key)throw new Error("Cole uma chave nova.");const result=await api("/api/ai/config",{method:"POST",body:JSON.stringify({apiKey:key,provider,model:$("aiModel").value.trim()}),timeoutMs:42000});$("aiKey").value="";$("aiStatus").textContent=result.migrationRequired?"⚠ Chave preservada, mas a migração para Auth AQ. é necessária.":`✓ Geração estruturada validada · ${result.provider==="gemini"?"Gemini":"OpenAI"} · ${result.model}`;toast(result.migrationRequired?"Chave salva; migração necessária":"Chave salva e geração validada",result.migrationRequired);}catch(error){$("aiStatus").textContent=error.message;toast(error.message,true);}}
async function removeAi(){try{await api("/api/ai/config",{method:"DELETE"});$("aiStatus").textContent="Chave removida.";toast("Chave de IA removida");}catch(error){toast(error.message,true);}}
async function diagnoseAi(showToast=true){const b=$("aiTest");b.disabled=true;try{const result=await api("/api/ai/test",{method:"POST",body:"{}",timeoutMs:42000});const stages=Object.entries(result.stages||{}).map(([name,status])=>`${name.toUpperCase()} ${status==="ok"?"✓":"…"}`).join(" · ");$("aiStatus").textContent=`IA OPERACIONAL · ${result.displayName||result.model} · ${result.latencyMs} ms · ${stages}`;if(showToast)toast("Geração estruturada validada de ponta a ponta");return result;}catch(error){$("aiStatus").textContent=`Falha no diagnóstico: ${error.message}`;if(showToast)toast(error.message,true);throw error;}finally{b.disabled=false;}}
async function testAi(){try{await diagnoseAi(true);}catch{}}
async function readAi(){const b=$("aiRead"),symbol=state.symbol,interval=state.interval,analysis=state.analysis,generation=++state.aiGeneration,started=Date.now();b.disabled=true;const progress=setInterval(()=>{if(generation===state.aiGeneration)$("aiResult").textContent=`Preparando e validando a leitura complementar… ${Math.round((Date.now()-started)/1000)} s`;},1000);$("aiResult").textContent="Validando o retrato exato exibido…";try{if(!analysis?.id)throw new Error("Atualize a leitura antes de pedir a IA.");const out=await api("/api/ai/read",{method:"POST",body:JSON.stringify({analysisId:analysis.id,symbol,interval}),timeoutMs:42000});if(generation===state.aiGeneration&&symbol===state.symbol&&interval===state.interval){const meta=`${out.context.symbol.replace("USDT","/USDT")} · ${out.context.interval}\nAnálise: ${new Date(out.context.analysisCalculatedAt).toLocaleTimeString("pt-BR")} · IA: ${new Date(out.context.generatedAt).toLocaleTimeString("pt-BR")}\nModelo: ${out.provider}/${out.model} · Request: ${out.requestId||"não informado"}\nAnalysis ID: ${out.context.analysisId}${out.context.signalId?` · Signal ID: ${out.context.signalId}`:""}`;$("aiResult").textContent=`${meta}\n\n${formatAi(out.content)}`;}}catch(error){if(generation===state.aiGeneration)$("aiResult").textContent=`Não foi possível gerar a leitura: ${error.message}`;}finally{clearInterval(progress);if(generation===state.aiGeneration)b.disabled=false;}}
function formatAi(v){if(typeof v==="string")return v;const format=value=>Array.isArray(value)?value.map(item=>typeof item==="object"?JSON.stringify(item):String(item)).join(" · "):value&&typeof value==="object"?JSON.stringify(value,null,2):String(value??"");return Object.entries(v||{}).map(([key,value])=>`${key.replace(/_/g," ").toUpperCase()}: ${format(value)}`).join("\n\n");}
